function layoutControls(){if(!keyboardLayoutInfo)return '';const presets=keyboardLayoutInfo.presets||[],layout=keyboardLayoutInfo.layout,known=presets.some(p=>p.id===layout.id);return `<div class="layout-controls"><select id="keyboard-layout" class="compact-select" aria-label="${h(state.language==='en'?'Keyboard layout':'键盘布局')}">${known?'':`<option value="custom" selected>${h(layout.name)}</option>`}${presets.map(p=>`<option value="${h(p.id)}" ${p.id===layout.id?'selected':''}>${h(p.name)}</option>`).join('')}</select><button class="small-button" data-action="edit-layout">${icon('settings')}${h(state.language==='en'?'Customize':'自定义布局')}</button></div>`}
