async function loadTasks(){const r=await command('tasks:list');state.tasks=Array.isArray(r)?r:(r?.tasks||[]);for(const x of state.tasks){const draft=dirtyFields.get(x.id);if(draft)Object.assign(x,draft)}if(state.selected&&!state.tasks.some(x=>x.id===state.selected))state.selected=null;updateCount()}
async function loadStats(){const b=rangeBounds(state.activityRange,'activity');const tRange=state.timelineRange==='follow'?state.activityRange:state.timelineRange;const tb=rangeBounds(tRange,state.timelineRange==='follow'?'activity':'timeline');const rb=rangeBounds(state.rankingRange,'ranking');const heatStart=new Date();heatStart.setHours(0,0,0,0);heatStart.setDate(heatStart.getDate()-181);const results=await Promise.allSettled([call('stats:query',b),call('stats:query',tb),call('stats:query',rb),call('stats:query',{start_ms:heatStart.getTime(),end_ms:Date.now()+1}),call('capture:status')]);state.stats=results[0].status==='fulfilled'?results[0].value:emptyStats();state.timelineStats=results[1].status==='fulfilled'?results[1].value:emptyStats();state.rankingStats=results[2].status==='fulfilled'?results[2].value:emptyStats();state.heatStats=results[3].status==='fulfilled'?results[3].value:emptyStats();state.capture=results[4].status==='fulfilled'?results[4].value:null;const failure=results.find(x=>x.status==='rejected');if(failure)state.error=String(failure.reason?.message||failure.reason)}
