function applyLocale(){document.documentElement.lang=state.language==='en'?'en':'zh-CN';$$('[data-i18n]').forEach(e=>e.textContent=t(labelMap[e.dataset.i18n]));const theme=$('#theme'),language=$('#language');if(theme){theme.value=state.theme;for(const option of theme.options){const names={light:'浅色',dark:'深色',system:'跟随系统'};option.textContent=t(names[option.value])}}if(language)language.value=state.language}
function effectiveTheme(){return state.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):state.theme}
function markdownPresentation(){return {theme:effectiveTheme(),language:state.language,placeholder:t(state.editor?'写下任务描述…':'补充背景、链接，或写下你打算怎么做…')}}
