function applyRuntimeLocale(previousLanguage){applyLocale();syncMarkdownPresentation();if(state.tray)renderTray();else if(state.editor)localizeRuntime($('#app'),previousLanguage);else if($('#details-frame')){localizeRuntime($('#left'),previousLanguage);localizeRuntime($('#detail'),previousLanguage);applySplit()}else renderCurrent();if(datePicker){const active=document.activeElement,action=active?.dataset?.action;renderDatePicker(action==='picker-day'?{focusDay:true}:action?{focusAction:action}:{})}}
let settingsSequence=0;
