function renderEditor(){document.body.classList.add('tray-body');const shell=$('#app');shell.classList.add('editor-shell');const task=taskById(state.selected);if(!task){shell.innerHTML=`<p class="muted">${h(t('任务不存在'))}</p>`;return}const children=state.tasks.filter(x=>x.parent_id===task.id).sort((a,b)=>(Number(a.completed_at!=null)-Number(b.completed_at!=null))||((a.subtask_order??-1)-(b.subtask_order??-1)));shell.innerHTML=`<div class="floating-editor"><div class="floating-bar"><button class="detail-done" data-action="toggle" data-id="${h(task.id)}"><span class="status-circle ${task.completed_at?'done':''}" aria-hidden="true"></span></button><select id="priority" class="compact-select"><option value="0" ${!task.priority?'selected':''}>${h(t('无优先级'))}</option><option value="1" ${task.priority===1?'selected':''}>${h(t('低'))}</option><option value="2" ${task.priority===2?'selected':''}>${h(t('中'))}</option><option value="3" ${task.priority===3?'selected':''}>${h(t('高'))}</option></select><span class="spacer"></span><button data-action="delete" data-id="${h(task.id)}" title="${h(t('删除'))}" aria-label="${h(t('删除'))}">${icon('delete')}</button><button data-action="tray-close-editor" aria-label="${h(t('关闭'))}">${icon('dismiss')}</button></div><div class="floating-content"><input class="detail-title" id="detail-title" value="${h(task.title)}" aria-label="${h(t('标题'))}"><input id="plan-date" type="date" value="${h(stampToLocal(task.planned_at))}" aria-label="${h(t('计划日期'))}"><iframe class="editor markdown-frame" id="details-frame" src="./markdown-editor.html" title="Markdown" data-task="${h(task.id)}"></iframe>${task.parent_id?'':`<div class="detail-label">${h(t('子任务'))} <span class="muted">${children.filter(x=>x.completed_at).length}/${children.length}</span></div>${children.map(x=>taskRow(x,true)).join('')}<div class="child-add">${taskAddButton('new-child','添加子任务')}<input id="new-child" placeholder="${h(t('添加子任务'))}"></div>`}</div></div>`;initializeMarkdown()}

async function refreshStats(){await loadStats()}
async function setSetting(key,value){state.settings[key]=value;try{await command('settings:set',{key,value})}catch{}}
async function refreshAll(){try{if(editing||splitDragging){pendingChange=true;return}if(!await flushPendingEdits())return;const settings=await call('settings:get');if(settings){state.settings=settings;state.theme=settings.theme||'system';state.language=settings.language==='en'?'en':'zh';if(!splitDragging)state.splitRatio=validSplitRatio(settings.splitRatio)}await loadTasks();await loadStats();if(editing||splitDragging){pendingChange=true;return}if(!await flushPendingEdits())return;renderCurrent()}catch(e){renderError()}}
const saveTimers=new Map(),dirtyFields=new Map(),flushRequests=new Map(),taskWriteChains=new Map();let editing=false,pendingChange=false,flushSerial=0;
