async function flushPendingEdits(){const id=state.selected,frame=$('#details-frame');if(id&&frame){const initial=markdownFrames.get(frame);if(!initial){state.error='Editor was not initialized';renderError();return false}const ready=await Promise.race([initial.ready,new Promise(resolve=>setTimeout(()=>resolve(false),2000))]);if(!ready||$('#details-frame')!==frame){state.error='Editor did not initialize in time';renderError();return false}const request=++flushSerial;const value=await new Promise(resolve=>{flushRequests.set(request,resolve);frame.contentWindow.postMessage({type:'toccata-flush',request},'*');setTimeout(()=>{if(flushRequests.has(request)){flushRequests.delete(request);resolve(null)}},1500)});if(value===null){state.error='Unable to save editor content';renderError();return false}const task=taskById(id);if(task&&task.details!==value)scheduleDraft('details',value,id)}if(id){const title=$('#detail-title');if(title&&title.value!==taskById(id)?.title)scheduleDraft('title',title.value,id)}const ids=new Set([...dirtyFields.keys(),...taskWriteChains.keys()]);for(const taskId of ids){const inFlight=taskWriteChains.get(taskId);if(inFlight){const ok=await inFlight;if(!ok&&!dirtyFields.has(taskId))return false}const patch=dirtyFields.get(taskId);if(!patch)continue;if('title' in patch&&!patch.title.trim()){state.error='Title cannot be empty';renderError();return false}for(const field of Object.keys(patch)){const key=taskId+':'+field;clearTimeout(saveTimers.get(key));saveTimers.delete(key)}if(!await updateTask(taskId,{...patch},false))return false}return dirtyFields.size===0&&taskWriteChains.size===0} 
